-- Adds a 'QC Approval — Queue' work queue to aria:qc-approval, matching the
-- exact dataSources + WorkflowQueueList shape used by aria:loading-allocation /
-- aria:dispatch-vehicle-details: a named GET /api/workflow/queue-for-page
-- dataSource, cardFields incl. vehicleNo/flowVariantCode, fillFormOnSelect so
-- picking a queue card populates the form below, and priorityShading.

UPDATE page_version pv JOIN page_definition pd ON pd.id = pv.page_id
SET pv.body_json = '{"kind":"layout","schemaVersion":2,"slug":"aria:qc-approval","title":"QC Approval","status":"published","version":1,"roles":["QC","Manager","TenantAdmin"],"dataSources":[{"id":"q","kind":"rest","method":"GET","url":"/api/workflow/queue-for-page?pageCode=aria:qc-approval"}],"streams":[],"layout":[{"kind":"Grid","columns":12,"gap":16,"children":[{"kind":"Section","title":"Sample Identification","span":12,"children":[{"kind":"Form","submitLabel":"","bindings":{"fields":[{"name":"gp_number","label":"Gate Pass # (scan / pick / type)","type":"select","required":true,"scannable":true,"freeSolo":true,"optionsSource":{"type":"datasource","spec":{"type":"entity","entity":"GatePass","joins":[{"entity":"WorkflowInstance","as":"wi","on":"gate_pass.workflow_instance_id = wi.id"}],"filter":{"and":[{"field":"wi.assigned_role","op":"eq","value":"QC"},{"field":"wi.status","op":"eq","value":"OPEN"}]},"select":["id","gp_number"],"sort":[{"field":"gp_number","dir":"desc"}]},"valueField":"gp_number","labelField":"gp_number"},"onChangeFill":{"item_category":"item_category","flow_variant_code":"flow_variant_code","instanceId":"workflow_instance_id"}},{"name":"item_category","label":"Item Category (auto-fill from dispatch entry)","type":"select","required":true,"options":[{"label":"RM Oil — bottled / canned / drum","value":"RM_OIL"},{"label":"RM Other — jaggery / agarbatti raw","value":"RM_OTHER"},{"label":"Packing — cartons / cases","value":"PACK_CARTON"},{"label":"Packing — bottles / cans","value":"PACK_BOTTLE"},{"label":"Packing — caps / labels","value":"PACK_SMALL"},{"label":"FG — packed for dispatch","value":"FG"},{"label":"Return Stock","value":"RETURN"}]},{"name":"sample_jar_id","label":"Sample / Sample Lot ID","type":"text","required":true,"placeholder":"SAMPLE-2026-0617"},{"name":"qc_officer_id","label":"QC Officer (auto-fill)","type":"text","readOnly":true},{"name":"flow_variant_code","label":"Flow Variant","type":"text","readOnly":true}]}}]},{"kind":"Section","title":"Oil Parameters (only if item category = RM Oil / FG)","span":12,"subtitle":"Skip this section if the receipt is packing material / return / non-oil.","children":[{"kind":"Form","bindings":{"fields":[{"name":"density_kgl","label":"Density (kg/L) — spec 0.910–0.930 for groundnut","type":"number"},{"name":"ffa_pct","label":"Free Fatty Acid (%) — spec ≤ 0.20","type":"number"},{"name":"colour_rating","label":"Colour vs reference","type":"select","options":[{"label":"Golden / Pale yellow — Pass","value":"PASS_GOLDEN"},{"label":"Light orange — Pass","value":"PASS_ORANGE"},{"label":"Dark brown — Fail","value":"FAIL_DARK"},{"label":"Cloudy — Fail","value":"FAIL_CLOUDY"}]},{"name":"temperature_c","label":"Temperature (°C) — spec ≤ 35","type":"number"}]}}]},{"kind":"Section","title":"Packing-Material Parameters (only if Packing)","span":12,"subtitle":"Skip if not packing material.","children":[{"kind":"Form","bindings":{"fields":[{"name":"print_quality","label":"Print quality (labels / cartons)","type":"select","options":["PASS","PASS_MINOR","FAIL_PRINT"]},{"name":"dimensional_check","label":"Dimensions match spec? (±2 mm)","type":"select","options":["PASS","MARGINAL","FAIL"]},{"name":"bottle_integrity","label":"Bottle integrity — burst pressure / cap fit","type":"select","options":["PASS","PARTIAL","FAIL_CRACK","FAIL_CAP_FIT"]},{"name":"carton_strength","label":"Carton strength — drop test","type":"select","options":["PASS","MARGINAL","FAIL"]}]}}]},{"kind":"Section","title":"FG / Return Inspection (only if FG / Return)","span":12,"subtitle":"Skip if not FG or return.","children":[{"kind":"Form","bindings":{"fields":[{"name":"seal_intact","label":"Seal intact?","type":"select","options":["YES","BROKEN","MISSING"]},{"name":"label_match","label":"Label matches SKU master?","type":"select","options":["YES","BATCH_MISMATCH","EXPIRY_MISMATCH","MRP_MISMATCH"]},{"name":"batch_expiry_check","label":"Within shelf life?","type":"select","options":["YES","NEAR_EXPIRY","EXPIRED"]}]}}]},{"kind":"Section","title":"Photo + Seal","span":12,"children":[{"kind":"Form","submitLabel":"","bindings":{"fields":[{"name":"sample_photo","label":"Sample Photo","type":"file","accept":"image/*"},{"name":"seal_unlock_no","label":"Seal Unlock #","type":"text"},{"name":"oil_sample_recovered","label":"Oil Sample Recovered (after seal lock)","type":"select","options":["YES","NO"],"visibleWhen":"#form.flow_variant_code == ''M10.TankerInbound''","requiredWhen":"#form.flow_variant_code == ''M10.TankerInbound''"},{"name":"unloading_supervisor_name","label":"Unloading Supervisor Name","type":"select","visibleWhen":"#form.flow_variant_code == ''M10.TankerInbound''","requiredWhen":"#form.flow_variant_code == ''M10.TankerInbound''","optionsSource":{"type":"datasource","spec":{"type":"entity","entity":"Employee","select":["id","employeename"],"filter":{"and":[{"field":"employeetype","op":"eq","value":"Supervisor"},{"field":"status","op":"eq","value":"A"}]},"sort":[{"field":"employeename","dir":"asc"}]},"valueField":"id","labelField":"employeename"}},{"name":"unloading_location","label":"Unloading Material / FG Stock Location","type":"select","options":[{"label":"G1 — Main Stores","value":"G1"},{"label":"G2 — Packing Material Stores","value":"G2"},{"label":"G3 — Returns / Quarantine","value":"G3"},{"label":"G4 — FG Stores","value":"G4"}],"visibleWhen":"#form.item_category == ''RETURN''","requiredWhen":"#form.item_category == ''RETURN''"},{"name":"qc_notes","label":"Notes","type":"textarea","rows":3}]}}]},{"kind":"Section","title":"Decision","span":12,"children":[{"kind":"Form","bindings":{"fields":[{"name":"status","label":"QC Decision","type":"select","required":true,"options":[{"label":"✓ APPROVED — all parameters pass","value":"APPROVED"},{"label":"✗ REJECTED — see notes / debit vendor","value":"REJECTED"}]},{"name":"qc_reject_reason","label":"Rejection Reason","type":"textarea","rows":3,"visibleWhen":"#form.status == ''REJECTED''","requiredWhen":"#form.status == ''REJECTED''"}]}},{"kind":"WorkflowActionButton","action":"workflow.transition","label":"Submit QC Decision","variant":"primary"}]},{"kind":"Section","title":"QC Approval — Queue","span":12,"subtitle":"Vehicles awaiting a QC decision.","children":[{"kind":"WorkflowQueueList","persona":"QC","dataSource":"q","pageSize":25,"cardFields":["gpNumber","vehicleNo","flowVariantCode","currentState"],"fillFormOnSelect":true,"priorityShading":true}]}]}]}'
WHERE pd.code = 'aria:qc-approval' AND pv.id = pd.current_version_id
  AND JSON_SEARCH(pv.body_json, 'one', 'WorkflowQueueList', NULL, '$.layout[*].children[*].children[*].kind') IS NULL;
